import java.lang.reflect.Field;

public class ReflectionEncapsulationDemo {
    private String secret = "Confidential Data";

    public static void main(String[] args) throws Exception {
        ReflectionEncapsulationDemo demo = new ReflectionEncapsulationDemo();

        Field field = ReflectionEncapsulationDemo.class.getDeclaredField("secret");

        // Breaking encapsulation explicitly
        field.setAccessible(true);

        String value = (String) field.get(demo);
        System.out.println("Extracted via reflection: " + value);

        field.set(demo, "Hacked State");
        System.out.println("Modified via reflection: " + demo.secret);
    }
}
